mapper.select:
select sum(temp1.SHARE_AMT) as totalAmt from (select temp.FINPROD_ID FINPROD_ID,0 as BRANCH,temp.CCY CCY, (case when C.ASSET_TYPE IN ('02','03') then temp.SHARE_AMT*100 else temp.SHARE_AMT end) as SHARE_AMT from (SELECT A.FINPROD_ID FINPROD_ID,A.CCY CCY,SUM(A.SHARE_AMT) as SHARE_AMT FROM PTL_SEC_VALUTION A where 1=1
AND A.CDATE = to_date(#{cdate}, 'yyyy-MM-dd')
group by A.FINPROD_ID,A.CCY) temp LEFT JOIN FIN_PRODUCT_TYPE B ON temp.FINPROD_ID=B.FINPROD_ID and B.BRANCH = 0 INNER JOIN ASSET_CLASS C ON B.TYPE_9=C.CUSTOM_ASSET_TYPE_TWO and B.TYPE_10=C.CUSTOM_ASSET_TYPE_THREE and B.TYPE_11=C.CUSTOM_ASSET_TYPE_FOUR and B.TYPE_12=C.CUSTOM_ASSET_TYPE_FIVE where 1=1
and C.IS_NONSTANDARD = #{isNonstandard}
) temp1

select NON_STANDARD_MAINT.NON_STANDARD_LIMIT,NON_STANDARD_MAINT.NON_STANDARD_ROTIO from NON_STANDARD_MAINT


        EFF_DATE<= #{effdate,jdbcType=DATE}


order by EFF_DATE desc

select temp1.PRD_DESIGN_ID proDesignid, sum(temp1.SHARE_AMT) as totalAmt,PTL_PORTFOLIO_VALUATION.TDY_ASSET_VALUE as tdyAssetValue from (select temp.PORTFOLIO_ID PORTFOLIO_ID,A.PRD_DESIGN_ID PRD_DESIGN_ID,temp.FINPROD_ID FINPROD_ID,0 as BRANCH,temp.CCY CCY, (case when C.ASSET_TYPE IN ('02','03') then temp.SHARE_AMT*100 else temp.SHARE_AMT end) as SHARE_AMT from (SELECT P.PORTFOLIO_ID PORTFOLIO_ID,P.FINPROD_ID FINPROD_ID,P.CCY CCY,SUM(P.SHARE_AMT) as SHARE_AMT FROM PTL_SEC_VALUTION P where P.CDATE = to_date(#{cdate}, 'yyyy-MM-dd') group by P.PORTFOLIO_ID,P.FINPROD_ID,P.CCY) temp INNER JOIN FIN_PRODUCT_ADD A ON A.PORTFOLIO_ID=temp.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT D ON D.FINPROD_ID=A.FINPROD_ID and D.FINPROD_TYPE2='F16' and D.P_FINPROD_ID is null LEFT JOIN FIN_PRODUCT_TYPE B ON temp.FINPROD_ID=B.FINPROD_ID and B.BRANCH = 0 INNER JOIN ASSET_CLASS C ON B.TYPE_9=C.CUSTOM_ASSET_TYPE_TWO and B.TYPE_10=C.CUSTOM_ASSET_TYPE_THREE and B.TYPE_11=C.CUSTOM_ASSET_TYPE_FOUR and B.TYPE_12=C.CUSTOM_ASSET_TYPE_FIVE where 1=1
and C.IS_NONSTANDARD = #{isNonstandard}
) temp1 left join PTL_PORTFOLIO_VALUATION on temp1.PORTFOLIO_ID=PTL_PORTFOLIO_VALUATION.PORTFOLIO_ID and PTL_PORTFOLIO_VALUATION.CDATE=to_date(#{cdate}, 'yyyy-MM-dd') group by temp1.PRD_DESIGN_ID,PTL_PORTFOLIO_VALUATION.TDY_ASSET_VALUE
